  ('g_rad_tolerance', 'module1'),  ('g_secure_ota', 'module1'),
  ('g_jam_detect', 'module2'), ('g_jam_suppress', 'module2'), ('g_spoof_detect', 'module2'),
  ('g_integrity', 'module2'),  ('g_nav_auth', 'module2'),     ('g_incident_log', 'module2'),
