INSERT INTO goal_texts (goal_id, lang, title, body) VALUES
  ('g_chain_of_trust', 'ru', 'Цепочка доверия от аппаратного корня', 'Неизменяемый загрузчик в ПЗУ проверяет подпись каждого следующего звена: загрузчика, ядра ОСРВ, задач. Неподписанный код не получает управления.'),
  ('g_chain_of_trust', 'en', 'Chain of trust from a hardware root', 'An immutable ROM bootloader checks the signature of every next stage: second-stage loader, RTOS kernel, application tasks. Unsigned code never runs.'),
  ('g_hw_isolation', 'ru', 'Аппаратная изоляция критических функций', 'Защищённый и незащищённый миры: ARM TrustZone (Cortex-M33/M55) и PMP для RISC-V. Ключи не покидают защищённого мира.'),
  ('g_hw_isolation', 'en', 'Hardware isolation of critical functions', 'Secure and non-secure worlds via ARM TrustZone (Cortex-M33/M55) and PMP on RISC-V. Keys never leave the secure world.'),
  ('g_tc_auth', 'ru', 'Аутентификация телекоманд', 'Каждая телекоманда подписана кодом аутентичности и защищена от повтора по протоколу CCSDS SDLS.'),
  ('g_tc_auth', 'en', 'Telecommand authentication', 'Every telecommand carries a MAC and is protected from replay with CCSDS SDLS.'),
  ('g_rad_tolerance', 'ru', 'Устойчивость к радиационным сбоям', 'EDAC/ECC, вычищение памяти, троирование критических переменных и сторожевой таймер — чтобы одиночный сбой не стал уязвимостью.'),
  ('g_rad_tolerance', 'en', 'Radiation fault tolerance', 'EDAC/ECC, memory scrubbing, triple modular redundancy and a watchdog, so a single upset never becomes a vulnerability.'),
  ('g_secure_ota', 'ru', 'Безопасное обновление прошивки', 'Проверка подписи до записи и откат к последнему проверенному образу (A/B-слоты).'),
  ('g_secure_ota', 'en', 'Secure firmware updates', 'Signature check before writing and rollback to the last known-good image (A/B slots).'),

  ('g_jam_detect', 'ru', 'Обнаружение помехи в реальном времени', 'По падению C/N₀, росту мощности в полосе и изменению АРУ.'),
  ('g_jam_detect', 'en', 'Real-time interference detection', 'From a drop in C/N₀, rising in-band power and AGC changes.'),
  ('g_jam_suppress', 'ru', 'Подавление помех', 'STAP на антенной решётке: провалы диаграммы направленности в сторону источников помех.'),
  ('g_jam_suppress', 'en', 'Interference suppression', 'STAP on an antenna array: pattern nulls steered at the jammers.'),
  ('g_spoof_detect', 'ru', 'Обнаружение подмены', 'Доплер, псевдодальности, углы прихода, часы и инерциальные данные должны описывать одно движение; расхождение выдаёт ложный сигнал.'),
  ('g_spoof_detect', 'en', 'Spoofing detection', 'Doppler, pseudoranges, angles of arrival, clock and inertial data must describe one motion; a mismatch exposes a fake signal.'),
  ('g_integrity', 'ru', 'Контроль целостности решения', 'RAIM/ARAIM: исключение аномальных спутников и вычисление защитного уровня.'),
  ('g_integrity', 'en', 'Solution integrity monitoring', 'RAIM/ARAIM: exclude faulty satellites and compute the protection level.'),
  ('g_nav_auth', 'ru', 'Подлинность навигационных сообщений', 'Galileo OSNMA там, где доступно.'),
  ('g_nav_auth', 'en', 'Navigation message authentication', 'Galileo OSNMA where available.'),
  ('g_incident_log', 'ru', 'Протоколирование инцидентов', 'Инциденты с меткой времени и координатами уходят в ситуационный центр LEXI Space.'),
  ('g_incident_log', 'en', 'Incident logging', 'Incidents with timestamp and position go to the LEXI Space situation center.'),

  ('g_hybrid', 'ru', 'Гибридное установление ключей', 'X25519 и ML-KEM работают одновременно: канал стоек, пока не взломаны оба.'),
  ('g_hybrid', 'en', 'Hybrid key establishment', 'X25519 and ML-KEM together: the channel holds until both are broken.'),
  ('g_pq_auth', 'ru', 'Постквантовая аутентификация', 'Подпись ключей устройств и служебных сообщений алгоритмом ML-DSA.'),
  ('g_pq_auth', 'en', 'Post-quantum authentication', 'Device keys and service messages are signed with ML-DSA.'),
  ('g_forward_secrecy', 'ru', 'Прямая секретность', 'Двойной храповик с постквантовым расширением: утечка одного ключа не раскрывает прошлое и будущее.'),
  ('g_forward_secrecy', 'en', 'Forward secrecy', 'Double Ratchet with a post-quantum extension: one leaked key exposes neither past nor future.'),
  ('g_device_data', 'ru', 'Защита данных на устройстве', 'SQLite, зашифрованная AES-256 (SQLCipher), ключ в аппаратном хранилище.'),
  ('g_device_data', 'en', 'On-device data protection', 'SQLite encrypted with AES-256 (SQLCipher), key kept in hardware storage.'),
  ('g_metadata_min', 'ru', 'Минимизация метаданных', 'Сервер не хранит историю и не видит содержимого.'),
  ('g_metadata_min', 'en', 'Metadata minimisation', 'The server keeps no history and never sees content.'),
  ('g_agility', 'ru', 'Криптографическая гибкость', 'Идентификаторы алгоритмов в протоколе и резервные схемы (SLH-DSA, HQC).'),
  ('g_agility', 'en', 'Crypto agility', 'Algorithm identifiers in the protocol and backup schemes (SLH-DSA, HQC).');

