INSERT INTO threat_texts (threat_id, lang, title, body, signs) VALUES
  ('t_cmd_injection', 'ru', 'Удалённый перехват управления', 'Злоумышленник со своей наземной станцией формирует или повторяет телекоманды в открытом канале «Земля — борт». Без аутентификации команда на сброс, разворот или включение двигателя исполняется как легитимная.', 'Команды вне окна связи центра управления, повтор уже использованного порядкового номера, неверный код аутентичности.'),
  ('t_cmd_injection', 'en', 'Remote command injection', 'An attacker with their own ground station crafts or replays telecommands on an open uplink. Without authentication a reset, slew or thruster command runs like a legitimate one.', 'Commands outside the control centre''s pass window, a reused sequence number, an invalid MAC.'),
  ('t_fw_spoof', 'ru', 'Подмена прошивки', 'Модифицированный образ загружается через механизм обновления или открытый отладочный порт JTAG/SWD. Закладка переживает перезагрузку и полностью компрометирует аппарат.', 'Хеш образа не совпадает с подписанным, неожиданная активность отладочного интерфейса.'),
  ('t_fw_spoof', 'en', 'Firmware spoofing', 'A modified image is loaded through the update path or a JTAG/SWD port left open after integration. The implant survives reboots and owns the spacecraft.', 'Image hash differs from the signed one, unexpected debug-port activity.'),
  ('t_isl_eaves', 'ru', 'Перехват межспутниковых каналов', 'Пассивный приём радио- или рассеянного лазерного излучения межспутниковой линии с соседнего аппарата. Без шифрования раскрываются телеметрия, ключи и топология группировки.', 'Обычно никаких — перехват пассивен. Поэтому шифрование обязательно заранее.'),
  ('t_isl_eaves', 'en', 'Inter-satellite link eavesdropping', 'Passive reception of the radio or scattered laser signal of an ISL from a nearby spacecraft. Without encryption it exposes telemetry, keys and constellation topology.', 'Usually none — interception is passive. That is why encryption must be there up front.'),
  ('t_fault_injection', 'ru', 'Внесение сбоев', 'Одиночные сбои от тяжёлых заряженных частиц или намеренные сбои питания и тактирования могут инвертировать бит проверки подписи и обойти безопасную загрузку.', 'Ошибки EDAC, срабатывания сторожевого таймера, расхождение копий TMR, пролёт через Южно-Атлантическую аномалию.'),
  ('t_fault_injection', 'en', 'Fault injection', 'Single-event upsets from heavy ions, or deliberate power and clock glitches, can flip the signature-check bit and bypass secure boot.', 'EDAC errors, watchdog resets, TMR copies disagreeing, passes through the South Atlantic Anomaly.'),
  ('t_supply_chain', 'ru', 'Атаки на цепочку поставок', 'Компрометация сторонних библиотек, компилятора или инструментов сборки до подписи образа.', 'Невоспроизводимая сборка, неожиданные зависимости, изменения в инструментах без ревью.'),
  ('t_supply_chain', 'en', 'Supply-chain attacks', 'Third-party libraries, the compiler or build tools are compromised before the image is signed.', 'Non-reproducible builds, unexpected dependencies, unreviewed toolchain changes.'),

  ('t_jamming', 'ru', 'Шумовое глушение (джамминг)', 'Навигационный сигнал у Земли — около −130 дБм, примерно на 20 дБ ниже теплового шума. Передатчик в единицы ватт за десятки километров лишает приёмник захвата. Бывает широкополосный шум, гармоника (CW), chirp и импульсные помехи.', 'Падение C/N₀ на всех спутниках сразу, рост мощности в полосе, АРУ уходит вниз.'),
  ('t_jamming', 'en', 'Jamming', 'A navigation signal arrives at about −130 dBm, roughly 20 dB below thermal noise. A transmitter of a few watts tens of kilometres away breaks the receiver''s lock. Broadband noise, CW tones, chirps and pulses.', 'C/N₀ drops on all satellites at once, in-band power rises, AGC gain falls.'),
  ('t_meaconing', 'ru', 'Ретрансляция (meaconing)', 'Подлинный сигнал записывается и переизлучается с задержкой: данные настоящие, а положение и время — ложные.', 'Скачок часов приёмника, одинаковая задержка у всех спутников, несоответствие доплера собственной скорости.'),
  ('t_meaconing', 'en', 'Meaconing', 'The genuine signal is recorded and rebroadcast with a delay: real navigation data, false position and time.', 'A receiver clock jump, the same extra delay on every satellite, Doppler not matching own velocity.'),
  ('t_spoofing', 'ru', 'Спуфинг координат', 'Синтетические сигналы всех видимых спутников с постепенным уводом решения (carry-off): приёмник незаметно переходит на ложный сигнал.', 'Все сигналы приходят с одного направления, C/N₀ слишком ровный и высокий, невязки EKF растут, решение расходится с инерциальной системой.'),
  ('t_spoofing', 'en', 'Position spoofing', 'Synthetic signals for every visible satellite with a gradual carry-off: the receiver quietly moves to the fake signal.', 'All signals arrive from one direction, C/N₀ too high and too even, EKF innovations grow, the fix drifts from the inertial solution.'),
  ('t_navmsg_tamper', 'ru', 'Нарушение целостности навигационного кадра', 'Подмена эфемерид, поправок часов или ионосферной модели даёт систематическую ошибку, которую без криптографической проверки не видно.', 'Эфемериды расходятся с независимым источником (например, с орбитальными элементами из каталога), сбой проверки OSNMA.'),
  ('t_navmsg_tamper', 'en', 'Navigation message tampering', 'Forged ephemerides, clock corrections or ionospheric parameters create a bias that is invisible without cryptographic checks.', 'Ephemerides disagree with an independent source (such as catalogue orbital elements), OSNMA verification fails.'),
  ('t_time_attack', 'ru', 'Атаки на шкалу времени', 'Сдвиг времени на единицы микросекунд ломает синхронизацию энергосистем, сетей связи и финансовых транзакций.', 'Расхождение с резервным эталоном (атомные часы, PTP), скачки поправки часов.'),
  ('t_time_attack', 'en', 'Timing attacks', 'A shift of a few microseconds breaks synchronisation of power grids, telecom networks and financial transactions.', 'Disagreement with a holdover reference (atomic clock, PTP), clock-bias jumps.'),
  ('t_space_weather', 'ru', 'Геомагнитные бури', 'Не атака, а природа: при сильных бурях растут ионосферные задержки и мерцания, приёмники теряют точность и захват, на орбите растёт число сбоев электроники.', 'Индекс Kp ≥ 5 (буря уровня G1 и выше), рост потока протонов.'),
  ('t_space_weather', 'en', 'Geomagnetic storms', 'Not an attack but nature: strong storms increase ionospheric delay and scintillation, receivers lose accuracy and lock, and on-orbit upsets rise.', 'Kp index ≥ 5 (G1 storm and above), rising proton flux.'),

  ('t_shor', 'ru', 'Алгоритм Шора', 'Квантовый компьютер с достаточным числом логических кубитов решает факторизацию и дискретный логарифм за полиномиальное время, порядка O(n³). Это ломает RSA, Диффи — Хеллмана, ECDH и ECDSA при любой длине ключа.', 'Не наблюдается напрямую. Оценивается по неравенству Моски и прогнозам появления квантовых компьютеров.'),
  ('t_shor', 'en', 'Shor''s algorithm', 'A quantum computer with enough logical qubits solves factoring and discrete logarithms in polynomial time, about O(n³). That breaks RSA, Diffie–Hellman, ECDH and ECDSA at any key size.', 'Not directly observable. Estimated with Mosca''s inequality and quantum-computing timelines.'),
  ('t_grover', 'ru', 'Алгоритм Гровера', 'Квадратичное ускорение перебора: стойкость симметричного ключа k бит падает до k/2. AES-256 и SHA-384 остаются достаточными, AES-128 меняется на AES-256.', 'Используются ключи короче 256 бит.'),
  ('t_grover', 'en', 'Grover''s algorithm', 'A quadratic speed-up of brute force: a k-bit symmetric key drops to k/2 bits. AES-256 and SHA-384 remain enough; AES-128 is replaced with AES-256.', 'Keys shorter than 256 bits in use.'),
  ('t_sndl', 'ru', 'Сохрани сейчас — расшифруй потом', 'Трафик записывают сегодня, чтобы расшифровать после появления квантового компьютера. Для оборонных и научных данных с долгим сроком секретности угроза актуальна уже сейчас.', 'Срок секретности данных плюс время миграции больше, чем время до квантового компьютера (x + y > z).'),
  ('t_sndl', 'en', 'Store now, decrypt later', 'Traffic is recorded today to be decrypted once a quantum computer exists. For defence and science data with long secrecy periods the threat is already real.', 'Secrecy lifetime plus migration time exceeds time to a quantum computer (x + y > z).'),
  ('t_impl_attacks', 'ru', 'Атаки на реализацию', 'Утечки по времени и энергопотреблению (KyberSlash), внесение сбоев, слабый генератор случайных чисел: стойкость алгоритма не спасает от ошибки в коде.', 'Время операции зависит от секрета, провал тестов на векторах NIST ACVP.'),
  ('t_impl_attacks', 'en', 'Implementation attacks', 'Timing and power leaks (KyberSlash), fault injection, weak randomness: a strong algorithm does not save buggy code.', 'Operation time depends on secrets, failures on NIST ACVP vectors.'),
  ('t_downgrade', 'ru', 'Понижение версии', 'Стороны принуждают договориться только о классическом алгоритме, без постквантовой части.', 'В согласованном наборе нет гибридной группы X25519MLKEM768.'),
  ('t_downgrade', 'en', 'Downgrade', 'The parties are forced to agree on a classical algorithm only, without the post-quantum part.', 'The negotiated suite lacks the X25519MLKEM768 hybrid group.');

