INSERT INTO countermeasure_texts (countermeasure_id, lang, title, body) VALUES
  ('c_secure_boot', 'ru', 'Безопасная загрузка', 'Образ исполняется, только если подпись разработчика сходится с открытым ключом в однократно программируемой памяти.'),
  ('c_secure_boot', 'en', 'Secure boot', 'An image runs only if the developer signature verifies against the public key in one-time-programmable memory.'),
  ('c_trustzone', 'ru', 'TrustZone / PMP', 'Ключи и криптография живут в защищённом мире; прикладной код туда не дотягивается.'),
  ('c_trustzone', 'en', 'TrustZone / PMP', 'Keys and crypto live in the secure world, out of reach of application code.'),
  ('c_sdls', 'ru', 'CCSDS SDLS', 'Код аутентичности на каждую телекоманду и окно анти-повтора по порядковому номеру.'),
  ('c_sdls', 'en', 'CCSDS SDLS', 'A MAC on every telecommand and an anti-replay window on the sequence number.'),
  ('c_edac_tmr', 'ru', 'EDAC, scrubbing, TMR, сторожевой таймер', 'Исправление ошибок памяти, периодическая перепроверка, три копии критических переменных с голосованием.'),
  ('c_edac_tmr', 'en', 'EDAC, scrubbing, TMR, watchdog', 'Memory error correction, periodic scrubbing, three voted copies of critical variables.'),
  ('c_ab_update', 'ru', 'Обновление A/B', 'Подпись проверяется до записи, при сбое аппарат откатывается на прошлый проверенный слот.'),
  ('c_ab_update', 'en', 'A/B updates', 'The signature is checked before writing; on failure the spacecraft rolls back to the last good slot.'),
  ('c_isl_crypto', 'ru', 'Шифрование межспутниковых линий', 'AEAD-шифрование всех межспутниковых каналов. Формула Фрииса показывает, с какого расстояния перехват реален.'),
  ('c_isl_crypto', 'en', 'ISL encryption', 'AEAD encryption on every inter-satellite link. The Friis equation shows from what distance interception is real.'),
  ('c_sast', 'ru', 'MISRA C и статический анализ', 'MISRA C:2023 и SEI CERT C в непрерывной интеграции: сборка с нарушениями обязательных правил блокируется.'),
  ('c_sast', 'en', 'MISRA C and static analysis', 'MISRA C:2023 and SEI CERT C in CI: a build with mandatory-rule violations is blocked.'),
  ('c_debug_lock', 'ru', 'Закрытие отладочных портов', 'JTAG/SWD блокируется после интеграции, доступ — только по криптографическому вызову.'),
  ('c_debug_lock', 'en', 'Debug-port lockdown', 'JTAG/SWD is locked after integration; access only through a cryptographic challenge.'),
  ('c_repro_build', 'ru', 'Воспроизводимая сборка', 'Один и тот же исходник даёт побитно один и тот же образ; зависимости зафиксированы и проверены.'),
  ('c_repro_build', 'en', 'Reproducible builds', 'The same source yields a bit-identical image; dependencies are pinned and verified.'),

  ('c_cn0_monitor', 'ru', 'Мониторинг C/N₀ и АРУ', 'Резкое падение C/N₀ на всех каналах сразу и уход АРУ — признак глушения.'),
  ('c_cn0_monitor', 'en', 'C/N₀ and AGC monitoring', 'A sudden C/N₀ drop on every channel together with AGC movement indicates jamming.'),
  ('c_stap', 'ru', 'STAP и MVDR', 'Антенная решётка ставит «нули» диаграммы в сторону помех; N элементов дают до N−1 провалов.'),
  ('c_stap', 'en', 'STAP and MVDR', 'The array steers pattern nulls at jammers; N elements give up to N−1 nulls.'),
  ('c_doppler_check', 'ru', 'Проверка доплера', 'Измеренный доплеровский сдвиг сравнивается с прогнозом по эфемеридам и собственной скорости.'),
  ('c_doppler_check', 'en', 'Doppler consistency check', 'Measured Doppler is compared with the prediction from ephemerides and own velocity.'),
  ('c_raim', 'ru', 'RAIM / ARAIM', 'Избыточные измерения: при 5 спутниках ошибку видно, при 6 — можно исключить виновника.'),
  ('c_raim', 'en', 'RAIM / ARAIM', 'Redundant measurements: 5 satellites detect a fault, 6 can exclude the culprit.'),
  ('c_osnma', 'ru', 'Galileo OSNMA', 'Криптографическая проверка навигационных сообщений по протоколу TESLA.'),
  ('c_osnma', 'en', 'Galileo OSNMA', 'Cryptographic navigation message authentication with the TESLA protocol.'),
  ('c_ekf_chi2', 'ru', 'EKF с тестом хи-квадрат', 'Фильтр Калмана предсказывает следующее измерение; если нормированная невязка больше квантиля χ², измерение аномально.'),
  ('c_ekf_chi2', 'en', 'EKF with chi-square test', 'The Kalman filter predicts the next measurement; if the normalised innovation exceeds the χ² quantile, the measurement is anomalous.'),
  ('c_incident_log', 'ru', 'Журнал инцидентов', 'Каждое срабатывание пишется с временем и координатами и уходит в ситуационный центр.'),
  ('c_incident_log', 'en', 'Incident log', 'Every alarm is logged with time and position and sent to the situation center.'),
  ('c_time_holdover', 'ru', 'Резервный эталон времени', 'Атомные часы или PTP держат время, пока навигационный сигнал под подозрением.'),
  ('c_time_holdover', 'en', 'Time holdover', 'An atomic clock or PTP keeps time while the navigation signal is suspect.'),
  ('c_ephemeris_xcheck', 'ru', 'Сверка эфемерид', 'Положения спутников из навигационного сообщения сверяются с независимым каталогом орбит (SGP4 по элементам CelesTrak).'),
  ('c_ephemeris_xcheck', 'en', 'Ephemeris cross-check', 'Satellite positions from the nav message are checked against an independent orbit catalogue (SGP4 from CelesTrak elements).'),
  ('c_kp_watch', 'ru', 'Наблюдение за космической погодой', 'Индекс Kp от NOAA: при бурях повышаем пороги и не путаем природу с атакой.'),
  ('c_kp_watch', 'en', 'Space-weather watch', 'NOAA Kp index: during storms thresholds are raised so nature is not mistaken for an attack.'),

  ('c_hybrid_kem', 'ru', 'Гибрид X25519 + ML-KEM-768', 'Два общих секрета объединяются через HKDF: чтобы получить ключ, нужно взломать оба механизма.'),
  ('c_hybrid_kem', 'en', 'X25519 + ML-KEM-768 hybrid', 'Two shared secrets are combined with HKDF: recovering the key needs both mechanisms broken.'),
  ('c_mldsa', 'ru', 'Подпись ML-DSA-65', 'Постквантовая подпись (FIPS 204) для ключей устройств и служебных данных. В LEXI Space ей подписаны данные с сервера.'),
  ('c_mldsa', 'en', 'ML-DSA-65 signatures', 'Post-quantum signatures (FIPS 204) for device keys and service data. LEXI Space signs its server data with it.'),
  ('c_ratchet', 'ru', 'Двойной храповик (PQ)', 'Ключи меняются с каждым сообщением; постквантовое расширение защищает от будущего квантового взлома.'),
  ('c_ratchet', 'en', 'Double Ratchet (PQ)', 'Keys change with every message; the post-quantum extension protects against future quantum attacks.'),
  ('c_sqlcipher', 'ru', 'SQLCipher', 'Локальная база зашифрована AES-256, ключ в Secure Enclave / StrongBox / TPM.'),
  ('c_sqlcipher', 'en', 'SQLCipher', 'The local database is AES-256 encrypted, key in Secure Enclave / StrongBox / TPM.'),
  ('c_aes256', 'ru', 'AES-256-GCM / ChaCha20-Poly1305', 'Симметричная часть с запасом: после Гровера остаётся не меньше 128 бит.'),
  ('c_aes256', 'en', 'AES-256-GCM / ChaCha20-Poly1305', 'The symmetric layer has margin: at least 128 bits remain after Grover.'),
  ('c_agility', 'ru', 'Криптогибкость', 'Идентификаторы алгоритмов в протоколе, резервные SLH-DSA и HQC.'),
  ('c_agility', 'en', 'Crypto agility', 'Algorithm identifiers in the protocol; SLH-DSA and HQC as backups.'),
  ('c_const_time', 'ru', 'Код с постоянным временем', 'Никаких ветвлений и обращений к памяти, зависящих от секрета; проверка на векторах NIST ACVP.'),
  ('c_const_time', 'en', 'Constant-time code', 'No secret-dependent branches or memory access; tested against NIST ACVP vectors.'),
  ('c_transcript_bind', 'ru', 'Привязка к транскрипту', 'Список предложенных алгоритмов входит в вывод ключа: подменить его незаметно нельзя.'),
  ('c_transcript_bind', 'en', 'Transcript binding', 'The offered algorithm list goes into key derivation, so it cannot be silently altered.');

-- ---------------------------------------------------------------------
--  Формулы
-- ---------------------------------------------------------------------
INSERT INTO formulas (id, module_id, latex, calc, result_unit, origin) VALUES
  -- Модуль 1
  ('f_mac',        'module1', 't = \mathrm{MAC}_K\left(SN \,\|\, TC\right)', NULL, NULL, 'portal'),
  ('f_tc_verify',  'module1', '\mathrm{Verify}_K\left(SN \,\|\, TC,\ t\right) = 1 \;\wedge\; SN > SN_{\mathrm{last}}', 'tcVerify', NULL, 'portal'),
  ('f_forge',      'module1', 'P_{\mathrm{forge}} \approx 2^{-\tau}', 'forgeProbability', NULL, 'portal'),
  ('f_secure_boot','module1', '\mathrm{Verify}\left(pk_{\mathrm{root}},\ H(FW),\ \sigma\right) = 1', NULL, NULL, 'portal'),
  ('f_seu',        'module1', '\lambda_{\mathrm{SEU}} = \sigma_{\mathrm{SEU}} \cdot \Phi', 'seuRate', '1/сутки', 'portal'),
  ('f_tmr',        'module1', 'R_{\mathrm{TMR}} = 3R^{2} - 2R^{3}', 'tmrReliability', NULL, 'portal'),
  ('f_friis',      'module1', 'P_r = P_t\, G_t\, G_r \left(\frac{\lambda}{4\pi d}\right)^{2}', 'friis', 'дБм', 'portal'),
  -- Модуль 2
  ('f_noise',      'module2', 'N_0 = kT', 'thermalNoise', 'дБм/Гц', 'portal'),
  ('f_cn0_eff',    'module2', '\left(\frac{C}{N_0}\right)_{\mathrm{eff}} = \left[\left(\frac{C}{N_0}\right)^{-1} + \frac{J/C}{Q\,R_c}\right]^{-1}', 'cn0Effective', 'дБ·Гц', 'portal'),
  ('f_doppler',    'module2', 'f_d = f_0\,\frac{v}{c}\cos\theta', 'doppler', 'Гц', 'portal'),
  ('f_pseudorange','module2', '\rho_i = \lVert \mathbf{r}_i - \mathbf{r}_u \rVert + c\,(\delta t_u - \delta t_i) + I_i + T_i + \varepsilon_i', 'pseudorange', 'км', 'portal'),
  ('f_mvdr',       'module2', '\mathbf{w} = \frac{\mathbf{R}^{-1}\mathbf{a}(\theta)}{\mathbf{a}^{H}(\theta)\,\mathbf{R}^{-1}\mathbf{a}(\theta)}', 'mvdrSuppression', 'дБ', 'portal'),
  ('f_ekf',        'module2', '\begin{aligned}\hat{\mathbf{x}}_{k|k-1} &= f\left(\hat{\mathbf{x}}_{k-1}\right)\\ \mathbf{P}_{k|k-1} &= \mathbf{F}_k\mathbf{P}_{k-1}\mathbf{F}_k^{T} + \mathbf{Q}_k\\ \boldsymbol{\nu}_k &= \mathbf{z}_k - h\left(\hat{\mathbf{x}}_{k|k-1}\right)\\ \mathbf{S}_k &= \mathbf{H}_k\mathbf{P}_{k|k-1}\mathbf{H}_k^{T} + \mathbf{R}_k\end{aligned}', NULL, NULL, 'portal'),
  ('f_chi2',       'module2', '\varepsilon_k = \boldsymbol{\nu}_k^{T}\mathbf{S}_k^{-1}\boldsymbol{\nu}_k > \chi^{2}_{m,\,1-\alpha}', 'chi2Test', NULL, 'portal'),
  ('f_visviva',    'module2', 'v^{2} = \mu\left(\frac{2}{r} - \frac{1}{a}\right)', 'visViva', 'км/с', 'portal'),
  ('f_period',     'module2', 'T = 2\pi\sqrt{\frac{a^{3}}{\mu}}', 'orbitalPeriod', 'мин', 'portal'),
  ('f_relativity', 'module2', '\frac{\Delta t}{t} \approx \frac{GM_{\oplus}}{c^{2}}\left(\frac{1}{R_{\oplus}} - \frac{1}{r}\right) - \frac{v^{2}}{2c^{2}}', 'gpsRelativity', 'мкс/сутки', 'portal'),
  -- Модуль 3
  ('f_mosca',      'module3', 'x + y > z', 'mosca', 'лет', 'portal'),
  ('f_mlwe',       'module3', '\mathbf{b} = \mathbf{A}\mathbf{s} + \mathbf{e} \pmod q', NULL, NULL, 'portal'),
  ('f_hybrid',     'module3', 'K = \mathrm{HKDF}\left(ss_{\text{ML-KEM}} \,\|\, ss_{\text{X25519}},\ \mathrm{transcript}\right)', 'hybridKey', NULL, 'portal'),
  ('f_grover',     'module3', 'k_{\mathrm{eff}} = k / 2', 'groverSecurity', 'бит', 'portal'),
  ('f_shor',       'module3', 'N_{\mathrm{ops}} \sim O(n^{3})', 'shorOps', NULL, 'portal'),
  -- Из сервера Гоши (исправлены единицы измерения)
  ('f_orbital_velocity', NULL, 'v = \frac{2\pi r}{T}', 'orbitalVelocity', 'км/с', 'gosha'),
  ('f_circular_velocity', NULL, 'v = \sqrt{\frac{GM}{r}}', 'circularVelocity', 'км/с', 'gosha'),
  -- Для карточек небесных объектов
  ('f_kepler3',    NULL, 'T^{2} = a^{3}', 'kepler3', 'лет', 'space'),
  ('f_escape',     NULL, 'v_{\mathrm{esc}} = \sqrt{\frac{2GM}{R}}', 'escapeVelocity', 'км/с', 'space'),
  ('f_light_time', NULL, 't = \frac{d}{c}', 'lightTime', 'мин', 'space'),
  ('f_abs_mag',    NULL, 'M = m - 5\log_{10}\frac{d}{10\ \mathrm{пк}}', 'absoluteMagnitude', NULL, 'space'),
  ('f_luminosity', NULL, '\frac{L}{L_{\odot}} = 10^{0.4\,(4.83 - M)}', 'luminosity', 'L☉', 'space'),
  ('f_star_temp',  NULL, 'T = 4600\left(\frac{1}{0.92\,(B-V) + 1.7} + \frac{1}{0.92\,(B-V) + 0.62}\right)', 'starTemperature', 'K', 'space'),
  ('f_hubble',     NULL, 'v = H_0\, d', 'hubbleVelocity', 'км/с', 'space');

INSERT INTO formula_texts (formula_id, lang, title, explanation) VALUES
  ('f_mac', 'ru', 'Код аутентичности телекоманды', 'К команде TC и её порядковому номеру SN прикладывается MAC на секретном ключе K.'),
  ('f_mac', 'en', 'Telecommand MAC', 'A MAC over the command TC and its sequence number SN with secret key K.'),
  ('f_tc_verify', 'ru', 'Проверка телекоманды на борту', 'Команда исполняется, только если MAC верный и номер больше последнего принятого — это и есть защита от повтора.'),
  ('f_tc_verify', 'en', 'On-board telecommand check', 'A command runs only if the MAC verifies and the number is above the last accepted one — that is the replay protection.'),
  ('f_forge', 'ru', 'Вероятность слепой подделки MAC', 'Для тега длиной τ бит угадать верный тег можно с вероятностью около 2^−τ. При τ = 128 это ничтожно мало.'),
  ('f_forge', 'en', 'Blind MAC forgery probability', 'For a τ-bit tag the chance of guessing a valid tag is about 2^−τ. At τ = 128 it is negligible.'),
  ('f_secure_boot', 'ru', 'Условие безопасной загрузки', 'Прошивка FW исполняется, если подпись σ её хеша сходится с корневым ключом.'),
  ('f_secure_boot', 'en', 'Secure boot condition', 'Firmware FW runs if the signature σ over its hash verifies against the root key.'),
  ('f_seu', 'ru', 'Частота одиночных сбоев', 'Сечение сбоя ячейки умножается на поток частиц. Умножив ещё на объём памяти, получаем ожидаемое число сбоев в сутки.'),
  ('f_seu', 'en', 'Single-event upset rate', 'Per-bit cross-section times particle flux. Multiplied by memory size it gives expected upsets per day.'),
  ('f_tmr', 'ru', 'Надёжность троирования', 'Три копии и голосование большинством. Выигрыш есть, пока надёжность одной копии больше 0,5.'),
  ('f_tmr', 'en', 'TMR reliability', 'Three copies with majority voting. It helps as long as one copy is more reliable than 0.5.'),
  ('f_friis', 'ru', 'Формула Фрииса: энергетика перехвата', 'Какая мощность дойдёт до приёмника злоумышленника на расстоянии d. Если она выше чувствительности приёмника, перехват физически возможен.'),
  ('f_friis', 'en', 'Friis equation: interception budget', 'How much power reaches an eavesdropper at distance d. If it beats the receiver sensitivity, interception is physically possible.'),
  ('f_noise', 'ru', 'Тепловой шум', 'Спектральная плотность шума N₀ = kT, около −174 дБм/Гц при 290 К.'),
  ('f_noise', 'en', 'Thermal noise', 'Noise density N₀ = kT, about −174 dBm/Hz at 290 K.'),
  ('f_cn0_eff', 'ru', 'Эффективное C/N₀ под помехой', 'Насколько падает отношение несущая/шум при помехе мощностью J. Ниже ~28 дБ·Гц приёмник обычно теряет слежение.'),
  ('f_cn0_eff', 'en', 'Effective C/N₀ under jamming', 'How far carrier-to-noise drops with jammer power J. Below about 28 dB-Hz a receiver usually loses tracking.'),
  ('f_doppler', 'ru', 'Доплеровский сдвиг', 'Сдвиг частоты из-за движения источника вдоль линии визирования. Расхождение с прогнозом выдаёт подмену.'),
  ('f_doppler', 'en', 'Doppler shift', 'Frequency shift from motion along the line of sight. A mismatch with the prediction reveals spoofing.'),
  ('f_pseudorange', 'ru', 'Модель псевдодальности', 'Геометрическое расстояние плюс ошибки часов, ионосферы, тропосферы и шум.'),
  ('f_pseudorange', 'en', 'Pseudorange model', 'Geometric range plus clock, ionosphere, troposphere errors and noise.'),
  ('f_mvdr', 'ru', 'Веса антенной решётки (MVDR)', 'Решётка сохраняет полезный сигнал и максимально давит всё остальное. Калькулятор считает, на сколько децибел подавлена помеха с заданного направления.'),
  ('f_mvdr', 'en', 'Array weights (MVDR)', 'The array keeps the wanted signal and suppresses everything else. The calculator shows how many dB a jammer from a given direction is suppressed.'),
  ('f_ekf', 'ru', 'Расширенный фильтр Калмана', 'Прогноз состояния и ковариации, невязка измерения и её ковариация.'),
  ('f_ekf', 'en', 'Extended Kalman filter', 'State and covariance prediction, measurement innovation and its covariance.'),
  ('f_chi2', 'ru', 'Тест хи-квадрат по невязке', 'Если нормированная невязка больше квантиля χ² с m степенями свободы, измерение считается аномальным.'),
  ('f_chi2', 'en', 'Chi-square innovation test', 'If the normalised innovation exceeds the χ² quantile with m degrees of freedom, the measurement is anomalous.'),
  ('f_visviva', 'ru', 'Формула vis-viva', 'Скорость на орбите по расстоянию r и большой полуоси a.'),
  ('f_visviva', 'en', 'Vis-viva equation', 'Orbital speed from distance r and semi-major axis a.'),
  ('f_period', 'ru', 'Период обращения', 'Третий закон Кеплера для спутника Земли.'),
  ('f_period', 'en', 'Orbital period', 'Kepler''s third law for an Earth satellite.'),
  ('f_relativity', 'ru', 'Релятивистский уход часов GPS', 'Гравитация ускоряет часы на орбите, скорость замедляет. Для GPS в сумме около +38 мкс в сутки, без поправки это около 11 км ошибки.'),
  ('f_relativity', 'en', 'GPS relativistic clock drift', 'Gravity speeds orbital clocks up, velocity slows them down. For GPS the net is about +38 µs per day, roughly 11 km of error if uncorrected.'),
  ('f_mosca', 'ru', 'Неравенство Моски', 'x — сколько лет данные должны быть секретны, y — время миграции, z — лет до квантового компьютера. Если x + y > z, переходить надо уже сейчас.'),
  ('f_mosca', 'en', 'Mosca''s inequality', 'x — years the data must stay secret, y — migration time, z — years to a quantum computer. If x + y > z, migration must start now.'),
  ('f_mlwe', 'ru', 'Задача Module-LWE', 'По A и b найти секрет s трудно и классически, и квантово. На этом держатся ML-KEM и ML-DSA.'),
  ('f_mlwe', 'en', 'Module-LWE problem', 'Recovering s from A and b is hard classically and quantumly. ML-KEM and ML-DSA rest on it.'),
  ('f_hybrid', 'ru', 'Гибридный ключ', 'Секреты ML-KEM и X25519 объединяются через HKDF. Калькулятор реально вырабатывает такой ключ в браузере.'),
  ('f_hybrid', 'en', 'Hybrid key', 'ML-KEM and X25519 secrets are combined with HKDF. The calculator really derives such a key in your browser.'),
  ('f_grover', 'ru', 'Стойкость после Гровера', 'Алгоритм Гровера вдвое снижает эффективную длину симметричного ключа.'),
  ('f_grover', 'en', 'Security after Grover', 'Grover''s algorithm halves the effective symmetric key length.'),
  ('f_shor', 'ru', 'Сложность алгоритма Шора', 'Порядок числа квантовых операций для взлома n-битного ключа RSA.'),
  ('f_shor', 'en', 'Shor''s algorithm cost', 'Order of quantum operations to break an n-bit RSA key.'),
  ('f_orbital_velocity', 'ru', 'Орбитальная скорость по периоду', 'Длина круговой орбиты, делённая на период. Из сервера Гоши.'),
  ('f_orbital_velocity', 'en', 'Orbital speed from period', 'Circumference of a circular orbit divided by the period. From Gosha''s server.'),
  ('f_circular_velocity', 'ru', 'Первая космическая на высоте', 'Скорость круговой орбиты на расстоянии r от центра Земли. Из сервера Гоши.'),
  ('f_circular_velocity', 'en', 'Circular orbital speed', 'Speed of a circular orbit at distance r from Earth''s centre. From Gosha''s server.'),
  ('f_kepler3', 'ru', 'Третий закон Кеплера', 'Для планет: период в годах, полуось в астрономических единицах.'),
  ('f_kepler3', 'en', 'Kepler''s third law', 'For planets: period in years, semi-major axis in AU.'),
  ('f_escape', 'ru', 'Вторая космическая скорость', 'Скорость, нужная, чтобы улететь с поверхности тела навсегда.'),
  ('f_escape', 'en', 'Escape velocity', 'Speed needed to leave a body''s surface for good.'),
  ('f_light_time', 'ru', 'Время света', 'Сколько идёт свет от объекта до нас — мы видим его таким, каким он был тогда.'),
  ('f_light_time', 'en', 'Light travel time', 'How long light takes to reach us — we see the object as it was back then.'),
  ('f_abs_mag', 'ru', 'Абсолютная звёздная величина', 'Каким был бы блеск звезды с расстояния 10 парсек.'),
  ('f_abs_mag', 'en', 'Absolute magnitude', 'How bright a star would look from 10 parsecs.'),
  ('f_luminosity', 'ru', 'Светимость', 'Во сколько раз звезда мощнее Солнца.'),
  ('f_luminosity', 'en', 'Luminosity', 'How many times more powerful than the Sun a star is.'),
  ('f_star_temp', 'ru', 'Температура по цвету (формула Бальестероса)', 'Показатель цвета B−V даёт температуру поверхности; по ней же раскрашены звёзды в 3D.'),
  ('f_star_temp', 'en', 'Temperature from colour (Ballesteros)', 'The B−V colour index gives surface temperature; stars in 3D are coloured with it.'),
  ('f_hubble', 'ru', 'Закон Хаббла', 'Скорость удаления галактики пропорциональна расстоянию (H₀ ≈ 70 км/с/Мпк). Для ближних галактик собственное движение важнее: M31 к нам приближается.'),
  ('f_hubble', 'en', 'Hubble''s law', 'Recession speed is proportional to distance (H₀ ≈ 70 km/s/Mpc). For nearby galaxies their own motion dominates: M31 is approaching us.');

INSERT INTO formula_params (formula_id, pos, name, symbol, unit, def, min, max, step, label_ru, label_en) VALUES
  ('f_tc_verify', 1, 'sn', 'SN', NULL, 1042, 0, 1e9, 1, 'Номер пришедшей команды', 'Incoming command number'),
  ('f_tc_verify', 2, 'snLast', 'SN_{last}', NULL, 1041, 0, 1e9, 1, 'Последний принятый номер', 'Last accepted number'),
  ('f_tc_verify', 3, 'macOk', 'Verify', NULL, 1, 0, 1, 1, 'MAC верный (1 — да, 0 — нет)', 'MAC valid (1 yes, 0 no)'),
  ('f_forge', 1, 'tau', '\tau', 'бит', 128, 8, 512, 8, 'Длина тега', 'Tag length'),
  ('f_seu', 1, 'sigma', '\sigma_{SEU}', 'см²/бит', 1e-14, 1e-18, 1e-8, NULL, 'Сечение сбоя', 'Upset cross-section'),
  ('f_seu', 2, 'flux', '\Phi', 'см⁻²·с⁻¹', 10, 0, 1e6, NULL, 'Поток частиц', 'Particle flux'),
  ('f_seu', 3, 'kbytes', 'M', 'КБ', 512, 1, 1e7, 1, 'Объём памяти', 'Memory size'),
  ('f_tmr', 1, 'r', 'R', NULL, 0.95, 0, 1, 0.01, 'Надёжность одной копии', 'Single-copy reliability'),
