INSERT INTO indicator_texts (indicator_id, lang, title, how) VALUES
  ('i_pq_signature', 'ru', 'Подпись данных ML-DSA-65', 'Сервер LEXI Space подписывает каждую порцию орбитальных данных постквантовой подписью ML-DSA-65 (FIPS 204). Браузер проверяет подпись открытым ключом. Если данные пришли не с нашего сервера — подписи нет, и это честно показано.'),
  ('i_pq_signature', 'en', 'ML-DSA-65 data signature', 'The LEXI Space server signs every batch of orbital data with ML-DSA-65 (FIPS 204). Your browser verifies it with the public key. If data came from elsewhere, there is no signature, and the panel says so.'),
  ('i_hybrid_key', 'ru', 'Гибридный ключ X25519 + ML-KEM-768', 'При загрузке страницы браузер проводит настоящее гибридное согласование ключей между двумя сторонами и сверяет, что обе получили один и тот же ключ через HKDF.'),
  ('i_hybrid_key', 'en', 'X25519 + ML-KEM-768 hybrid key', 'On load your browser runs a real hybrid key agreement between two parties and checks both derived the same HKDF key.'),
  ('i_tle_integrity', 'ru', 'Целостность орбитальных элементов', 'Каждая строка TLE проверяется по контрольной сумме (по модулю 10), считается возраст элементов. Старые элементы дают ошибку положения в километры.'),
  ('i_tle_integrity', 'en', 'Orbital element integrity', 'Every TLE line is checked with its mod-10 checksum and its age is computed. Old elements mean kilometres of position error.'),
  ('i_saa', 'ru', 'МКС и Южно-Атлантическая аномалия', 'По реальной орбите МКС проверяется, не пролетает ли она сейчас над аномалией, где поток протонов и риск сбоев электроники резко выше.'),
  ('i_saa', 'en', 'ISS and the South Atlantic Anomaly', 'Using the ISS''s real orbit we check whether it is now over the anomaly, where proton flux and electronics upset risk are much higher.'),
  ('i_gnss_geometry', 'ru', 'Геометрия GPS над вами', 'По реальным орбитам спутников GPS считается, сколько их видно из вашей точки и какой геометрический фактор PDOP. Чем он меньше, тем точнее координаты.'),
  ('i_gnss_geometry', 'en', 'GPS geometry above you', 'From real GPS orbits we count the satellites visible from your location and compute PDOP. Lower means a more accurate fix.'),
  ('i_raim', 'ru', 'Доступность RAIM', 'Для обнаружения сбойного спутника нужно не меньше 5 видимых, для исключения — 6. Считается по реальным орбитам для вашей точки.'),
  ('i_raim', 'en', 'RAIM availability', 'Detecting a faulty satellite needs at least 5 in view, excluding it needs 6. Computed from real orbits for your location.'),
  ('i_ekf_position', 'ru', 'Фильтр Калмана по вашей геолокации', 'Если разрешить геолокацию, координаты устройства идут через фильтр Калмана, а каждая новая точка проходит тест хи-квадрат. Невозможный скачок — признак сбоя или подмены.'),
  ('i_ekf_position', 'en', 'Kalman filter on your location', 'If you allow geolocation, device fixes run through a Kalman filter and each new fix gets a chi-square test. An impossible jump flags a fault or spoofing.'),
  ('i_kp', 'ru', 'Космическая погода (индекс Kp)', 'Планетарный индекс Kp от NOAA SWPC. При Kp ≥ 5 — геомагнитная буря, точность навигации падает.'),
  ('i_kp', 'en', 'Space weather (Kp index)', 'NOAA SWPC planetary Kp index. Kp ≥ 5 means a geomagnetic storm and degraded navigation accuracy.');

